create table if not exists public.tenants (id bigint generated by default as identity primary key, property text not null, name text not null, room text, sharing text, joined text, phone text, rent numeric default 0, deposit numeric default 0, dues numeric default 0, collection numeric default 0, last_payment text, created_at timestamptz default now());
create table if not exists public.payments (id bigint generated by default as identity primary key, tenant_id bigint references public.tenants(id) on delete set null, tenant_name text, property text, amount numeric not null, payment_date date default current_date, mode text default 'Cash', note text, created_at timestamptz default now());
create table if not exists public.expenses (id bigint generated by default as identity primary key, property text, category text, amount numeric not null, expense_date date default current_date, note text, created_at timestamptz default now());
create table if not exists public.complaints (id bigint generated by default as identity primary key, tenant_id bigint references public.tenants(id) on delete set null, tenant_name text, property text, room text, issue text not null, status text default 'Open', created_at timestamptz default now(), resolved_at timestamptz);
alter table public.tenants enable row level security; alter table public.payments enable row level security; alter table public.expenses enable row level security; alter table public.complaints enable row level security;
drop policy if exists tenants_auth_all on public.tenants; create policy tenants_auth_all on public.tenants for all to authenticated using (true) with check (true);
drop policy if exists payments_auth_all on public.payments; create policy payments_auth_all on public.payments for all to authenticated using (true) with check (true);
drop policy if exists expenses_auth_all on public.expenses; create policy expenses_auth_all on public.expenses for all to authenticated using (true) with check (true);
drop policy if exists complaints_auth_all on public.complaints; create policy complaints_auth_all on public.complaints for all to authenticated using (true) with check (true);
